-- Fakt kartochkalarining ruscha matni — 15-partiya:
-- Saroymulkxonim, Gavharshod begim, Kamoliddin Behzod.

-- ===== Saroymulkxonim =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Кем был отец Сарай-Мульк-ханым?', fact_ru = 'Я родилась в 1341 году — я дочь чагатайского хана Казанхана. Когда мне было пять лет, мой отец погиб.' WHERE id = 366;
UPDATE fact_cards SET topic_ru = 'Мой брак с Темуром', question_ru = 'Когда Амир Темур женился на Сарай-Мульк-ханым?', fact_ru = 'В 1370 году Амир Темур женился на мне.' WHERE id = 367;
UPDATE fact_cards SET topic_ru = 'Титул «Гураган»', question_ru = 'Почему Темур получил титул «Гураган»?', fact_ru = 'Оттого что я была ханской дочерью, Темур, женившись на мне, получил титул «Гураган» — «ханский зять».' WHERE id = 368;
UPDATE fact_cards SET topic_ru = 'Моё имя «Биби-ханым»', question_ru = 'Под каким именем Сарай-Мульк-ханым знали в народе?', fact_ru = 'Благодаря моему уму и рассудительности меня считали среди ханым «старшей ханым», и в народе я была известна под именем Биби-ханым.' WHERE id = 369;
UPDATE fact_cards SET topic_ru = 'Государственные дела', question_ru = 'Как Сарай-Мульк-ханым участвовала в государственных делах?', fact_ru = 'Я участвовала в государственных делах, а также сопровождала войско в походах.' WHERE id = 370;
UPDATE fact_cards SET topic_ru = 'Моё медресе', question_ru = 'Что построила Сарай-Мульк-ханым в Самарканде?', fact_ru = 'На драгоценности, оставшиеся мне от отца, я построила в Самарканде медресе и поддерживала обучение студентов.' WHERE id = 371;
UPDATE fact_cards SET topic_ru = 'Воспитание внуков', question_ru = 'Кому Темур доверил воспитание своих внуков?', fact_ru = 'Темур доверил мне воспитание своих внуков — мирз Улугбека, Мухаммада Султана и Халиля Султана.' WHERE id = 372;
UPDATE fact_cards SET topic_ru = 'Мечеть Биби-ханым', question_ru = 'В какие годы построена мечеть Биби-ханым?', fact_ru = 'В мою честь Темур в 1399–1404 годах возвёл в Самарканде огромную соборную мечеть — она из числа крупнейших памятников Средней Азии.' WHERE id = 373;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умерла Сарай-Мульк-ханым и где она погребена?', fact_ru = 'По сообщению Ибн Арабшаха, я скончалась в 1408 году; погребена в мавзолее подле моего медресе.' WHERE id = 374;
UPDATE fact_cards SET topic_ru = 'Свидетельство Клавихо', question_ru = 'Какой испанский посол видел Биби-ханым (Сарай-Мульк-ханым) на дворцовых пирах в Самарканде в 1404 году и записал это в своём дневнике?', fact_ru = 'В 1404 году в Самарканд прибыл посол Испании Руи Гонсалес де Клавихо. Он видел меня на дворцовых пирах и с почтением написал обо мне в своём дневнике.' WHERE id = 1772;
UPDATE fact_cards SET topic_ru = 'Дворцовые пиры', question_ru = 'Какое место занимала Биби-ханым (Сарай-Мульк-ханым) среди цариц на дворцовых пирах?', fact_ru = 'На больших празднествах и пирах, устраивавшихся в самаркандских садах, самое высокое место среди цариц доставалось мне, потому что я была старшей ханым двора.' WHERE id = 1773;
UPDATE fact_cards SET topic_ru = 'Столица Самарканд', question_ru = 'В каком городе Биби-ханым (Сарай-Мульк-ханым) провела большую часть своей жизни?', fact_ru = 'Амир Темур избрал столицей державы Самарканд. Большую часть своей жизни я провела в этом прекрасном городе.' WHERE id = 1774;
UPDATE fact_cards SET topic_ru = 'Мой мавзолей', question_ru = 'Где расположен мавзолей Биби-ханым (Сарай-Мульк-ханым)?', fact_ru = 'В Самарканде напротив мечети Биби-ханым для меня был воздвигнут мавзолей. Его и сегодня посещают под именем «мавзолей Биби-ханым».' WHERE id = 1775;
UPDATE fact_cards SET topic_ru = 'В списке Всемирного наследия', question_ru = 'Когда город Самарканд, где расположены памятники Биби-ханым, был внесён в список Всемирного наследия ЮНЕСКО?', fact_ru = 'Я скончалась в 1408 году. Много веков спустя, в 2001 году, город Самарканд, где я жила и возводила памятники, был внесён в список Всемирного наследия ЮНЕСКО. Памятники Биби-ханым — тоже часть этого наследия; услышав такое, представь, как я радуюсь!' WHERE id = 1776;
UPDATE fact_cards SET topic_ru = 'Мой внук Улугбек', question_ru = 'Кто из внуков, воспитанных Биби-ханым (Сарай-Мульк-ханым), стал великим учёным?', fact_ru = 'Одним из внуков, которых я воспитала, был Мирзо Улугбек. Он вырос великим учёным и построил в Самарканде знаменитую обсерваторию.' WHERE id = 1777;
UPDATE fact_cards SET topic_ru = 'Предания обо мне', question_ru = 'Что широко распространено в народе об имени Биби-ханым и её мечети?', fact_ru = 'В народе сложено множество преданий обо мне и о постройке моей мечети. Историки же помнят меня прежде всего как мудрую и почитаемую царицу двора.' WHERE id = 1778;

-- ===== Gavharshod begim =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Кем был отец Гавхаршад-бегим?', fact_ru = 'Я родилась в 1379 году. Мой отец — чагатайский вельможа Гиясиддин Тархан.' WHERE id = 375;
UPDATE fact_cards SET topic_ru = 'Моё замужество', question_ru = 'За кого вышла замуж Гавхаршад-бегим?', fact_ru = 'В 1393 году я вышла замуж за сына Темура — Шахруха Мирзу.' WHERE id = 376;
UPDATE fact_cards SET topic_ru = 'Мои дети', question_ru = 'Кто были знаменитые сыновья Гавхаршад-бегим?', fact_ru = 'Среди моих сыновей — правитель-астроном Улугбек Мирзо и покровитель искусств Байсункар Мирзо.' WHERE id = 377;
UPDATE fact_cards SET topic_ru = 'Дела державы', question_ru = 'Кто вёл дела державы, когда Шахрух был занят науками?', fact_ru = 'Когда Шахрух предавался молитве и наукам, делами державы и дивана на деле ведала я.' WHERE id = 378;
UPDATE fact_cards SET topic_ru = 'Назначение сановников', question_ru = 'В каких делах государственного управления участвовала Гавхаршад-бегим?', fact_ru = 'Я участвовала в назначении наместников и военачальников, в определении наград и наказаний.' WHERE id = 379;
UPDATE fact_cards SET topic_ru = 'Мои медресе', question_ru = 'Сколько медресе построила Гавхаршад-бегим в Герате?', fact_ru = 'В Герате я построила два больших медресе.' WHERE id = 380;
UPDATE fact_cards SET topic_ru = 'Другие мои постройки', question_ru = 'Какие здания, кроме медресе, возвела Гавхаршад-бегим?', fact_ru = 'Я возвела мечети, ханаки, лечебницы и караван-сараи.' WHERE id = 381;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Чем завершилась жизнь Гавхаршад-бегим?', fact_ru = 'В 1457 году, примерно на восьмидесятом году жизни, я была казнена по приказу Абусаида Мирзы.' WHERE id = 382;
UPDATE fact_cards SET topic_ru = 'Место моего погребения', question_ru = 'Где погребена Гавхаршад-бегим?', fact_ru = 'Я погребена в мавзолее Байсункара подле медресе, построенного мной самой.' WHERE id = 383;
UPDATE fact_cards SET topic_ru = 'Значение моего имени', question_ru = 'Что означает имя Гавхаршад-бегим?', fact_ru = 'Моё имя составлено из двух слов: «гавхар» — драгоценная жемчужина, «шад» — радостный. То есть имя моё означает «жемчужина радости».' WHERE id = 1592;
UPDATE fact_cards SET topic_ru = 'Мой свёкор Амир Темур', question_ru = 'Кем приходилась Гавхаршад-бегим Амиру Темуру?', fact_ru = 'Великий сахибкиран Амир Темур был моим свёкром — я была супругой его сына Шахруха Мирзы.' WHERE id = 1593;
UPDATE fact_cards SET topic_ru = 'Герат — наша столица', question_ru = 'Какой город был столицей державы Тимуридов во времена Гавхаршад-бегим?', fact_ru = 'Мой супруг Шахрух Мирза перенёс столицу державы из Самарканда в Герат. Большую часть жизни я провела в Герате.' WHERE id = 1594;
UPDATE fact_cards SET topic_ru = 'Моя мечеть в Мешхеде', question_ru = 'Какое здание построила Гавхаршад-бегим в городе Мешхед?', fact_ru = 'В городе Мешхед я построила огромную соборную мечеть. Её и сейчас называют «мечетью Гавхаршад», и она славится своими прекрасными изразцами.' WHERE id = 1595;
UPDATE fact_cards SET topic_ru = 'Мой зодчий Кавамиддин', question_ru = 'Какой зодчий составлял проекты зданий, построенных Гавхаршад-бегим?', fact_ru = 'Проекты возведённых мной зданий составлял знаменитейший зодчий того времени Кавамиддин Ширази.' WHERE id = 1596;
UPDATE fact_cards SET topic_ru = 'Моё покровительство наукам', question_ru = 'Каким городом прославился Герат во времена Гавхаршад-бегим?', fact_ru = 'Я покровительствовала учёным, поэтам и живописцам. В моё время Герат стал одним из крупнейших центров культуры Востока.' WHERE id = 1597;
UPDATE fact_cards SET topic_ru = 'Мой сын Улугбек', question_ru = 'Какой сын Гавхаршад-бегим стал знаменитым учёным?', fact_ru = 'Мой сын Мирзо Улугбек был правителем в Самарканде и как знаменитый учёный построил обсерваторию. Я им горжусь.' WHERE id = 1598;

-- ===== Kamoliddin Behzod =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда родился и когда умер Камалиддин Бехзад?', fact_ru = 'Я родился примерно в 1455 году, а скончался в 1535 году. И после моей смерти имя моё не забылось — в 2020 году отмечалось 565-летие со дня моего рождения.' WHERE id = 357;
UPDATE fact_cards SET topic_ru = 'Как я стал главой школы', question_ru = 'В каком возрасте Камалиддин Бехзад стал главой гератской школы миниатюры?', fact_ru = 'В двадцать три года я стал главой гератской школы миниатюры.' WHERE id = 358;
UPDATE fact_cards SET topic_ru = 'Моё звание', question_ru = 'Каким именем называют Камалиддина Бехзада?', fact_ru = 'Меня называют «Рафаэлем Востока».' WHERE id = 359;
UPDATE fact_cards SET topic_ru = 'Мои портреты', question_ru = 'Чьи портреты писал Камалиддин Бехзад?', fact_ru = 'Я написал портреты Абдурахмана Джами, Алишера Навои, Хусейна Байкары и Шейбанихана.' WHERE id = 360;
UPDATE fact_cards SET topic_ru = 'Жанр портрета', question_ru = 'Мастером какого жанра восточной миниатюры считается Камалиддин Бехзад?', fact_ru = 'Меня считают мастером и зачинателем жанра портрета в восточной миниатюре.' WHERE id = 361;
UPDATE fact_cards SET topic_ru = 'Заказ правителя', question_ru = 'Какой правитель поручил Бехзаду создавать миниатюры?', fact_ru = 'Правитель Герата Хусейн Байкара поручил мне создать новые произведения-миниатюры.' WHERE id = 362;
UPDATE fact_cards SET topic_ru = '«Портрет художника»', question_ru = 'Когда Бехзад создал произведение «Портрет художника»?', fact_ru = 'Своё произведение «Портрет художника» я создал в 1487 году.' WHERE id = 363;
UPDATE fact_cards SET topic_ru = 'Моя знаменитая работа', question_ru = 'Какой портрет Бехзада изучали западные учёные?', fact_ru = 'Мой портрет «Багдадский дервиш» изучали и западные учёные.' WHERE id = 364;
UPDATE fact_cards SET topic_ru = 'Моё наследие', question_ru = 'Как признаются работы Камалиддина Бехзада?', fact_ru = 'Признано, что мои работы обогатили сокровищницы искусства Востока и Запада.' WHERE id = 365;
UPDATE fact_cards SET topic_ru = 'Моё детство', question_ru = 'Какой художник взял Камалиддина Бехзада на воспитание в его детстве?', fact_ru = 'В детстве я остался сиротой. Знаменитый гератский художник Мирак Наккаш взял меня на воспитание и обучил тайнам живописи.' WHERE id = 1681;
UPDATE fact_cards SET topic_ru = 'Покровительство Навои', question_ru = 'Какой великий поэт покровительствовал Камалиддину Бехзаду?', fact_ru = 'Великий поэт Алишер Навои покровительствовал мне и поддерживал моё дарование.' WHERE id = 1682;
UPDATE fact_cards SET topic_ru = 'Дворцовая книжная мастерская', question_ru = 'На какую должность назначил Камалиддина Бехзада Хусейн Байкара?', fact_ru = 'Правитель Хусейн Байкара назначил меня главой дворцовой книжной мастерской в Герате. Там трудились лучшие мастера, украшавшие рукописные книги рисунками.' WHERE id = 1683;
UPDATE fact_cards SET topic_ru = 'Мои годы в Тебризе', question_ru = 'В каком городе Камалиддин Бехзад провёл последние годы жизни?', fact_ru = 'Последние годы жизни я провёл в городе Тебриз и руководил тамошней дворцовой книжной мастерской.' WHERE id = 1684;
UPDATE fact_cards SET topic_ru = 'Моё имя в «Бабурнаме»', question_ru = 'В каком произведении Захириддин Мухаммад Бабур упомянул Камалиддина Бехзада с похвалой?', fact_ru = 'Захириддин Мухаммад Бабур в произведении «Бабурнаме» упомянул меня как живописца с самым тонким пером своего времени.' WHERE id = 1685;
UPDATE fact_cards SET topic_ru = 'Искусство миниатюры', question_ru = 'Мастером какого вида искусства был Камалиддин Бехзад?', fact_ru = 'Миниатюра — это мелкий и чрезвычайно изящный рисунок, исполняемый на страницах рукописной книги. Я был мастером именно этого искусства.' WHERE id = 1686;
UPDATE fact_cards SET topic_ru = 'Институт моего имени', question_ru = 'Какое высшее учебное заведение в Ташкенте носит имя Камалиддина Бехзада?', fact_ru = 'Национальный институт художеств и дизайна в Ташкенте носит моё имя — там учатся будущие художники.' WHERE id = 1687;
